  const nga = new Set();
  for (let i = 0; i <= ta.length - 2; i++) nga.add(ta.slice(i,i+2).join(' '));
  for (let i = 0; i <= tb.length - 2; i++) { if (nga.has(tb.slice(i,i+2).join(' '))) return true; }
  return false;
}
function isSameEvent(a, b) {
  return titleJaccard(a.title, b.title) >= 0.45 || hasNgram2(a.title, b.title);
}
function sameDay(a, b) {
  const da = parseDate(a.published_date) || dateFromUrl(a.url);
  const db = parseDate(b.published_date) || dateFromUrl(b.url);
  if (!da || !db) return false;
  return da.getFullYear() === db.getFullYear() &&
         da.getMonth()    === db.getMonth()    &&
         da.getDate()     === db.getDate();
}

const eventDeduped = [];
const eventRemoved = new Set();
for (let i = 0; i < deduped.length; i++) {
  if (eventRemoved.has(i)) continue;
  for (let j = i + 1; j < deduped.length; j++) {
    if (eventRemoved.has(j)) continue;
    // 같은 날 + 동일 이벤트 → j 제거 (한자 치환 + 2-gram 병행)
    if (sameDay(deduped[i], deduped[j]) && isSameEvent(deduped[i], deduped[j])) {
      eventRemoved.add(j);
      deduped[i].sources = [...new Set([...(deduped[i].sources || []), ...(deduped[j].sources || [])])];
      if (String(deduped[j].summary||'').length > String(deduped[i].summary||'').length) {
        deduped[i].summary = deduped[j].summary;
      }
    }
  }
  if (!eventRemoved.has(i)) eventDeduped.push(deduped[i]);
}
const eventDuplicateCount = deduped.length - eventDeduped.length;
deduped = eventDeduped;

let dateFilteredCount = 0;
let excludedKeywordCount = 0;

const scored = [];
for (const item of deduped) {
  if (hasExclude(item)) { excludedKeywordCount++; continue; }
  // must_include 키워드가 제목+요약에 없으면 제외
  if (!hasMustInclude(item)) { excludedKeywordCount++; continue; }
  const dr = inRange(item);
  if (!dr.ok) { dateFilteredCount++; continue; }
  const kScore = keywordScore(item);
  const sScore = sourceQuality(item.url, item.source);
  const dScore = dr.score;
  const cScore = contentDepth(item);
  const multiSourceBoost = (item.sources || []).length >= 2 ? 0.06 : 0;
  const heuristic = Math.min(1, kScore*0.42 + sScore*0.25 + dScore*0.18 + cScore*0.15 + multiSourceBoost);
  scored.push({
    ...item,
    date_validation: dr.reason,
    needs_date_check: !!dr.needsDateCheck,
    source_quality_score: Math.round(sScore*100),
    keyword_match_score: Math.round(kScore*100),
    freshness_score: Math.round(dScore*100),
    content_depth_score: Math.round(cScore*100),
    heuristic_score: Math.round(heuristic*1000)/1000,
    score: Math.round(heuristic*1000)/1000,
    domain: domainOf(item.url),
    publisher: publisherOf(item.url, item.publisher)
  });
}

scored.sort((a,b) => b.heuristic_score - a.heuristic_score);
const candidates = scored.slice(0, meta.candidate_max || 30).map((x,i) => ({ ...x, candidate_rank: i+1 }));

const scoringInput = candidates.map((x,i) => ({
  no: i+1,
  title: x.title,
  url: x.url,
  summary: x.summary,
  source: x.source,
  sources: x.sources,
  published_date: x.published_date,
  domain: x.domain,
  heuristic_score: x.heuristic_score,
  source_quality_score: x.source_quality_score,
  date_validation: x.date_validation
}));

const scoringPrompt = `너는 기업 보직자용 리서치 자료를 선별하는 분석가다.
아래 후보 자료를 사용자의 검색 의도에 맞춰 평가하라.

