  naver_count: naverNewsList.length + naverWebList.length,
  duplicate_count: urlDuplicateCount + (Array.from(byUrl.values()).length - eventDeduped.length - eventDuplicateCount) + eventDuplicateCount,
  date_filtered_count: dateFilteredCount,
  excluded_keyword_count: excludedKeywordCount,
  candidate_count: candidates.length,
