const base = $('2. Code - 입력 정리 + 검색어 생성 프롬프트').first().json;
const raw = $json.text || $json.output || $json.response || $json.result || JSON.stringify($json);

function extractJson(str) {
  if (typeof str !== 'string') return str;
  let s = str.trim();
  s = s.replace(/^```json\s*/i,'').replace(/^```\s*/,'').replace(/```$/,'').trim();
  const first = s.indexOf('{');
  const last = s.lastIndexOf('}');
  if (first >= 0 && last >= first) s = s.slice(first, last + 1);
  return JSON.parse(s);
}

let parsed;
try { parsed = extractJson(raw); }
catch(e) {
  parsed = {
    search_intent: base.keyword,
    ko_queries: [base.keyword],
    en_queries: [],
    must_include: base.core_keywords || [],
    must_exclude: base.exclude_keywords || [],
    extracted_date_range: { start_date: null, end_date: null, reason: 'parse error' }
  };
}

const uniq = (arr) => [...new Set((arr || []).map(x => String(x).trim()).filter(Boolean))];

let koQueries = uniq(parsed.ko_queries);
let enQueries = uniq(parsed.en_queries);
if (!koQueries.length && base.keyword) koQueries = [base.keyword];

// AI가 재구성한 검색어만으로는, 사용자가 입력한 문구 그대로 브라우저에서 구글 검색하면
// 나오는 기사가 하나도 안 걸리는 경우가 실사용 중 확인됨(재구성 과정에서 문구가 바뀌면
// 그 기사가 어느 쿼리로도 안 걸릴 수 있음). 원문 그대로의 검색어를 항상 1순위로 넣어서
// 최소한 "사용자가 그 문구로 직접 검색했을 때"와 동일한 재현율을 보장한다.
if (base.keyword) {
  koQueries = [base.keyword, ...koQueries.filter(q => q !== base.keyword)];
}

koQueries = koQueries.slice(0, 5);
enQueries = enQueries.slice(0, 5);

// AI가 자체 판단으로 붙인 쌍따옴표(예: "주택대부"처럼 고유명사가 아닌 일반 용어에도
// 쌍따옴표를 붙이는 경우)는 Google/Naver가 그 문구를 문자 그대로 정확히 포함한 페이지만
// 찾게 만들어서, 언론에서 실제로 다른 표현(예: "주택대출")을 쓰면 결과가 아예 0건이 되는
// 위험이 있음(실사용 중 확인된 사례). 사용자가 직접 쌍따옴표로 감싼 경우(must_include_from_keyword)만
// 신뢰하고, AI가 임의로 붙인 쌍따옴표는 전부 제거한다 — 정말 필요한 건 바로 아래
// must_include 강제 삽입 단계에서 다시 붙는다.
koQueries = koQueries.map(q => q.replace(/"/g, ''));

// ── 날짜 범위 결정: 사용자 설정 > AI 추출 > time_range ──
const userSetStart = base.start_date || null;
const userSetEnd   = base.end_date   || null;
const userHasDate  = !!(userSetStart || userSetEnd);

const extractedRange = parsed.extracted_date_range || {};
const extractedStart = (!userHasDate && extractedRange.start_date && extractedRange.start_date !== 'null')
  ? extractedRange.start_date : null;
const extractedEnd   = (!userHasDate && extractedRange.end_date && extractedRange.end_date !== 'null')
  ? extractedRange.end_date : null;

let effectiveStartDate = userSetStart || extractedStart || null;
let effectiveEndDate   = userSetEnd   || extractedEnd   || null;

// base에 반영 (7번 노드 날짜 필터에서 사용)
if (effectiveStartDate) base.start_date = effectiveStartDate;
if (effectiveEndDate)   base.end_date   = effectiveEndDate;

// ── tbs 파라미터 생성 ──
function toMDY(s) {
  const d = new Date(s);
  if (isNaN(d.getTime())) return null;
  return `${d.getMonth()+1}/${d.getDate()}/${d.getFullYear()}`;
}

let tbs = null;
if (effectiveStartDate || effectiveEndDate) {
  const min = effectiveStartDate ? toMDY(effectiveStartDate) : '1/1/2000';
  const max = effectiveEndDate   ? toMDY(effectiveEndDate)   : toMDY(new Date().toISOString());
  if (min && max) tbs = `cdr:1,cd_min:${min},cd_max:${max}`;
} else if (base.time_range) {
  const map = { day:'qdr:d', week:'qdr:w', month:'qdr:m', year:'qdr:y' };
  tbs = map[base.time_range] || null;
}

// ── must_include 강제 삽입 (ko_queries만, en_queries는 영어 그대로) ──
const mustIncludeKw = base.must_include_from_keyword || [];
if (mustIncludeKw.length) {
  koQueries = koQueries.map(q => {
    const qClean = q.replace(/"/g, '');
    const missing = mustIncludeKw.filter(k => !qClean.includes(k));
    return missing.length ? `${missing.map(k => `"${k}"`).join(' ')} ${q}` : q;
  });
}

// ── Serper 쿼리 조합 (선택한 국가에 맞는 언어 배치만, 최대 8개) ──
// 예전엔 국가 선택과 무관하게 ko_queries+en_queries를 항상 둘 다 검색해서, '한국'을 선택해도
// en_queries(gl:'us' 고정) 배치가 그대로 섞여 들어가는 문제가 있었음(실사용 중 제보).
// country가 KR이면 한국어 배치만, 그 외 국가면 영어 배치를 선택한 국가의 gl로 검색한다.
const isKR = String(base.country || 'KR').toUpperCase() === 'KR';
const serperQueries = isKR
  ? koQueries.map(q => ({ q, hl:'ko', gl: base.gl || 'kr', language:'ko' }))
  : enQueries.map(q => ({ q, hl:'en', gl: base.gl || 'us', language:'en' }));

// ── Naver 쿼리 (쌍따옴표 제거, must_include 키워드는 앞에 추가) ──
const naverMustKw = base.must_include_from_keyword || [];
const naverQueries = koQueries.slice(0, 5).map(q => {
  let naverQ = q.replace(/"/g, ''); // 쌍따옴표 제거
  // must_include 키워드가 쿼리에 없으면 앞에 추가 (쌍따옴표 없이)
  for (const k of naverMustKw) {
    if (!naverQ.includes(k)) naverQ = `${k} ${naverQ}`;
  }
  return { q: naverQ, language: 'ko' };
});

// ── Serper jobs 생성 ──
const SERPER_PAGES = 2;
const serper_jobs = [];
for (const q of serperQueries) {
  for (let page = 1; page <= SERPER_PAGES; page++) {
    serper_jobs.push({
      endpoint: base.topic === 'news'
        ? 'https://google.serper.dev/news'
        : 'https://google.serper.dev/search',
      q: q.q,
      hl: q.hl,
      gl: q.gl,
      num: 10,
      page,
      filter: 0,
      autocorrect: false,
      tbs,
      language: q.language
    });
  }
}

// ── Naver jobs 생성 ──
const naver_news_jobs = naverQueries.map(q => ({
  query: q.q,
  display: 30,
  sort: (base.start_date || base.end_date || base.time_range) ? 'date' : 'sim'
}));

const naver_web_jobs = naverQueries.slice(0, 3).map(q => ({
  query: q.q,
  display: 20
}));

return {
  ...base,
  search_intent:        parsed.search_intent || base.keyword,
  ko_queries:           koQueries,
  en_queries:           enQueries,
  must_include:         uniq(parsed.must_include || base.core_keywords),
  must_exclude:         uniq(parsed.must_exclude || base.exclude_keywords),
  serper_jobs,
  naver_news_jobs,
  naver_web_jobs,
  generated_query_raw:  parsed,
  extracted_date_range: extractedRange,
  effective_start_date: effectiveStartDate,
  effective_end_date:   effectiveEndDate
};

const data = $json.body || $json;
const tp = data.tavily_params || {};

// Google Docs에 저장한 회사/업무 맥락 문서
// company_context_doc_id 또는 company_context_doc_url 모두 허용
// company_context_doc_url 기본값 (미입력 시 기본 문서 사용)
const DEFAULT_COMPANY_CONTEXT_URL = 'https://docs.google.com/document/d/1FML9a8fOGfi4SsF19SWqWAEMpImaZRD1SjlLwp5ne00/edit?usp=drive_link';
const companyContextInput = String(
  data.company_context_doc_url ||
  data.company_context_google_doc_url ||
  data.company_context_doc_id ||
  data.company_context_google_doc_id ||
  tp.company_context_doc_url ||
  tp.company_context_doc_id ||
  ''
).trim();

function extractGoogleDocId(input) {
  const s = String(input || '').trim();
  if (!s) return '';
  const m = s.match(/\/document\/d\/([^\/]+)/);
  if (m) return m[1];
  return s;
}

const companyContextDocId = extractGoogleDocId(companyContextInput);
const companyContextDocUrl = companyContextDocId
  ? `https://docs.google.com/document/d/${companyContextDocId}/edit`
  : DEFAULT_COMPANY_CONTEXT_URL;

const splitList = (v) => {
  if (Array.isArray(v)) return v.map(x => String(x).trim()).filter(Boolean);
  if (typeof v === 'string') return v.split(/[,，\n]+/).map(x => x.trim()).filter(Boolean);
  return [];
};

const rawKeyword = String(data.keyword || tp.query || '').trim();
const keyword = rawKeyword;

// 쌍따옴표로 감싼 단어 추출 → must_include (반드시 포함 키워드)
const quotedMatches = rawKeyword.match(/"([^"]+)"/g) || [];
const mustIncludeFromKeyword = quotedMatches.map(m => m.replace(/"/g, '').trim()).filter(Boolean);
const coreKeywords = splitList(data.core_keywords || data.main_keywords || keyword);
// 쌍따옴표 키워드를 coreKeywords 앞에 추가 (중복 제외)
for (const k of mustIncludeFromKeyword) {
  if (!coreKeywords.includes(k)) coreKeywords.unshift(k);
}
if (!coreKeywords.length && keyword) coreKeywords.push(keyword);

const expansionKeywords = splitList(data.expansion_keywords || data.sub_keywords || data.related_keywords || '');
const excludeKeywords = splitList(data.exclude_keywords || '');
const includeDomains = Array.isArray(tp.include_domains) ? tp.include_domains : splitList(data.include_domains || '');
const excludeDomains = Array.isArray(tp.exclude_domains) ? tp.exclude_domains : splitList(data.exclude_domains || '');

const topic = tp.topic || data.topic || 'news';
const timeRange = tp.time_range || data.time_range || null;

// days → start_date/end_date 자동 변환 (topic=news일 때)
let startDate = data.start_date || tp.start_date || null;
let endDate   = data.end_date   || tp.end_date   || null;

const days = tp.days ? Number(tp.days) : null;
if (days && !startDate && !endDate) {
  // days가 설정됐고 날짜 범위가 없으면 자동 계산
  const today = new Date();
  const from  = new Date();
  from.setDate(today.getDate() - days);
  startDate = from.toISOString().slice(0, 10);
  endDate   = today.toISOString().slice(0, 10);
}

const finalMax = Number(tp.max_results || data.max_results || 20);
const candidateMax = Number(data.candidate_max || 50);

const analysisViewpoint = data.analysis_viewpoint || 'business_expansion';
const reportType = data.report_type || 'trend_brief';
const audienceLevel = data.audience_level || 'division_head';
const reportDepth = data.report_depth || 'standard';
const actionOrientation = data.action_orientation !== undefined ? data.action_orientation : true;
const riskSensitivity = data.risk_sensitivity || 'normal';

const country = (tp.country || data.country || 'KR').toString();
const gl = country.slice(0,2).toLowerCase();

const todayStr = new Date().toISOString().slice(0, 10);

const queryPrompt = `너는 웹 리서치 검색어 설계 전문가다.
사용자의 키워드를 분석하여 검색어를 생성하고, 날짜 범위와 쌍따옴표 처리까지 판단하라.

[사용자 입력]
키워드: ${keyword}
핵심 키워드: ${coreKeywords.join(', ')}
확장 키워드: ${expansionKeywords.join(', ')}
제외 키워드: ${excludeKeywords.join(', ')}
분석 관점: ${analysisViewpoint}
리포트 유형: ${reportType}
사용자 설정 검색 기간: ${startDate || '미설정'} ~ ${endDate || '미설정'}
오늘 날짜: ${todayStr}

[쌍따옴표 처리 원칙]
- 사용자가 이미 쌍따옴표로 감싼 키워드는 반드시 그대로 유지
- 고유명사(기업명·기관명·인명·브랜드·법률명 등)는 쌍따옴표 추가
- 일반 키워드는 쌍따옴표 없이 그대로 사용
- 예) 삼성전자 → "삼성전자", 노란봉투법 → "노란봉투법", 동향 → 동향

[날짜 범위 추출 원칙]
- 사용자 키워드에서 시점 표현을 감지하여 날짜 범위를 계산하라
- "지난 N년" → start_date = 오늘로부터 N년 전, end_date = 오늘
- "지난 N개월" / "최근 N개월" → start_date = 오늘로부터 N개월 전, end_date = 오늘
- "최근" (단독) → start_date = 오늘로부터 3개월 전, end_date = 오늘
- "YYYY년" → start_date = YYYY-01-01, end_date = YYYY-12-31
- "YYYY" (4자리 연도) → 위와 동일
- 시점 표현 없으면 → start_date와 end_date 모두 null
- 사용자가 날짜를 이미 설정했으면 (미설정 아님) → 사용자 설정을 우선하고 extracted_date_range는 null로

[검색어 생성 원칙]
- ko_queries: 한국어 검색어 3~5개
- en_queries: 영어 검색어 3~5개
- 각 쿼리에 쌍따옴표 처리된 핵심 키워드를 반드시 포함
- 각 검색어는 120자 이하
- must_include 키워드는 ko_queries에만 포함시켜라. en_queries에는 영어 키워드만 사용하라
- exclude_keywords는 절대 쿼리에 넣지 말라. -키워드, NOT 연산자 형태도 금지. 후처리에서 처리한다
- 쿼리에는 찾고 싶은 긍정 키워드만 넣어라
- JSON 객체만 출력

[출력 형식]
{
  "search_intent": "검색 의도 한 문장",
  "ko_queries": ["한국어 검색어1", "한국어 검색어2"],
  "en_queries": ["english query 1", "english query 2"],
  "must_include": ["핵심 포함 개념 (쌍따옴표 포함 형태로)"],
  "must_exclude": ["제외 개념"],
  "extracted_date_range": {
    "start_date": "YYYY-MM-DD 또는 null",
    "end_date": "YYYY-MM-DD 또는 null",
    "reason": "날짜 추출 근거 한 문장"
  }
}`;

return {
  keyword,
  core_keywords: coreKeywords,
  expansion_keywords: expansionKeywords,
  exclude_keywords: excludeKeywords,
  include_domains: includeDomains,
  exclude_domains: excludeDomains,
  start_date: startDate,
  end_date: endDate,
  time_range: timeRange,
  topic,
  final_max: finalMax,
  candidate_max: candidateMax,
  country,
  gl,
  analysis_viewpoint: analysisViewpoint,
  report_type: reportType,
  audience_level: audienceLevel,
  report_depth: reportDepth,
  action_orientation: actionOrientation,
  risk_sensitivity: riskSensitivity,
  requested_at: data.requested_at || new Date().toISOString(),
  must_include_from_keyword: mustIncludeFromKeyword,
  company_context_doc_id: companyContextDocId,
  company_context_doc_url: companyContextDocUrl,
  query_prompt: queryPrompt
};

// 7-E. Tavily Extract 대상 선정 — 두 가지 이유로 후보를 고른다
// (1) 관련성이 애매한 후보(0.5~0.7) — 본문을 보면 판단이 명확해질 수 있음
// (2) 날짜 필터가 걸려있는데 날짜를 못 찾은 후보 — 본문에서 실제 게시일을 못 찾으면
//     최종 제외되므로, 우선순위를 (2) > (1)로 둔다(날짜 미상은 방치하면 통째로 탈락하지만,
//     관련성 애매는 방치해도 기존 프롬프트 판단으로만 처리될 뿐 완전히 사라지진 않음).
const prev = $input.first().json;
const candidates = prev.candidates || [];

const AMBIG_MIN = 0.50;
const AMBIG_MAX = 0.70;
const EXTRACT_CAP = 20; // Tavily Extract는 1회 호출당 최대 20 URL

const dateCheckItems = candidates.filter(c => c.needs_date_check).slice(0, EXTRACT_CAP);
const remainingSlots = Math.max(0, EXTRACT_CAP - dateCheckItems.length);
const ambiguousItems = candidates
  .filter(c => !c.needs_date_check && c.heuristic_score >= AMBIG_MIN && c.heuristic_score < AMBIG_MAX)
  .slice(0, remainingSlots);

const targets = [...dateCheckItems, ...ambiguousItems];
const purposeByUrl = {};
targets.forEach(c => {
  purposeByUrl[c.url] = {
    dateCheck: !!c.needs_date_check,
    relevance: c.heuristic_score >= AMBIG_MIN && c.heuristic_score < AMBIG_MAX
  };
});

return {
  ...prev,
  extract_target_urls: targets.map(c => c.url),
  extract_purpose_by_url: purposeByUrl,
  extract_needed: targets.length > 0
};

// 7-H. Tavily Extract 결과를 두 가지 용도로 병합
// (1) 관련성 애매 후보 → extracted_content 필드로 AI 평가 프롬프트에 추가
// (2) 날짜 미상 후보 → 본문 텍스트에서 실제 게시일을 정규식으로 찾아 검증
//     찾았고 기간 내면 살리고, 찾았는데 기간 밖이거나 끝내 못 찾으면 최종 제외한다.
const prev = $('7-E. Code - 애매 구간·날짜 미상 후보 선정').first().json;

const raw =
  $json.structuredContent ||
  $json.content?.[0]?.text ||
  $json.text ||
  $json.output ||
  JSON.stringify($json);

let parsed;
try { parsed = typeof raw === 'string' ? JSON.parse(raw) : raw; } catch(e) { parsed = null; }

const extractResults = parsed?.results || parsed?.content?.results || [];

const MAX_CONTENT_CHARS = 1200;
const contentByUrl = new Map();
for (const r of extractResults) {
  if (r?.url && r?.raw_content) contentByUrl.set(r.url, String(r.raw_content));
}

const purposeByUrl = prev.extract_purpose_by_url || {};
const start = prev.start_date ? new Date(prev.start_date) : null;
const end   = prev.end_date   ? new Date(prev.end_date + 'T23:59:59') : null;

// 기사 본문(마크다운)에서 게시일을 찾는다 — 메타태그는 마크다운 변환 과정에서 사라지므로
// 바이라인에 흔히 노출되는 눈에 보이는 날짜 텍스트를 정규식으로 찾는 방식.
function extractDateFromContent(text) {
  const s = String(text || '').slice(0, 3000); // 바이라인은 보통 본문 앞부분에 있음
  // 월/일 그룹은 2자리 형태(1[0-2], [12]\d, 3[01])를 먼저 시도해야 한다 — 1자리 형태를
  // 먼저 두면 정규식 교대(|)가 '16'에서 '1'만 매칭해버리는 등 오탐이 생김.
  const MM = '(1[0-2]|0?[1-9])';
  const DD = '([12]\\d|3[01]|0?[1-9])';
  let m = s.match(new RegExp(`(?:입력|등록|송고|수정)[^\\n0-9]{0,10}(20\\d{2})[.\\-/]\\s?${MM}(?!\\d)[.\\-/]\\s?${DD}(?!\\d)`));
  if (!m) m = s.match(new RegExp(`(20\\d{2})[.\\-/]${MM}(?!\\d)[.\\-/]${DD}(?!\\d)`));
  if (!m) m = s.match(new RegExp(`(20\\d{2})년\\s?${MM}(?!\\d)월\\s?${DD}(?!\\d)일`));
  if (!m) return null;
  const y = Number(m[1]), mo = Number(m[2]), d = Number(m[3]);
  if (mo < 1 || mo > 12 || d < 1 || d > 31) return null;
  const dt = new Date(y, mo - 1, d);
  return isNaN(dt.getTime()) ? null : dt.toISOString();
}
function isInFilterRange(iso) {
  const d = new Date(iso);
  if (start && d < start) return false;
  if (end && d > end) return false;
  return true;
}

let dateRecoveredCount = 0, dateExcludedCount = 0;

const merged = (prev.candidates || []).map(c => {
  const purpose = purposeByUrl[c.url];
  const rawContent = contentByUrl.get(c.url);
  let updated = { ...c };

  if (purpose?.relevance && rawContent) {
    updated.extracted_content = rawContent.slice(0, MAX_CONTENT_CHARS);
  }

  if (purpose?.dateCheck) {
    const foundIso = rawContent ? extractDateFromContent(rawContent) : null;
    if (foundIso && isInFilterRange(foundIso)) {
      dateRecoveredCount++;
      updated.published_date = foundIso;
      updated.date_validation = 'verified_from_content';
      updated.needs_date_check = false;
    } else {
      dateExcludedCount++;
      updated._excludeAfterCheck = true;
    }
  }
  return updated;
});

// extract 대상에 못 든 needs_date_check 후보(후보가 20개 초과)도 끝내 검증 못 한 것이므로 제외
const finalCandidates = merged
  .filter(c => !c._excludeAfterCheck && !c.needs_date_check)
  .map(({ _excludeAfterCheck, ...rest }) => rest);

return {
  ...prev,
  candidates: finalCandidates,
  candidate_count: finalCandidates.length,
  extract_success_count: contentByUrl.size,
  date_recovered_count: dateRecoveredCount,
  date_filtered_count: (prev.date_filtered_count || 0) + dateExcludedCount
};

// 7-I. 애매 구간/날짜 미상 후보가 전혀 없어 Tavily Extract를 건너뛴 경우 그대로 전달
// (7-E가 needs_date_check 후보를 항상 targets에 먼저 담으므로, 이 분기를 타면 애초에
//  검증이 필요한 후보가 없었다는 뜻 — 그대로 넘겨도 안전하다)
const prev = $('7-E. Code - 애매 구간·날짜 미상 후보 선정').first().json;
return { ...prev, extract_success_count: 0, date_recovered_count: 0 };

// 7-J. 7-H(추출함)/7-I(건너뜀) 중 실제로 실행된 쪽의 결과를 그대로 전달.
// 8-B/9가 후보 목록을 참조할 때 분기와 무관하게 이 노드 하나만 보면 되도록 하는 수렴점.
return $input.first().json;
